// Nội dung biên soạn tiếng Việt; không sao chép cheat sheet của Tutorials Dojo.
export const categories = [
 ['compute','Điện toán','Compute','orange'],['storage','Lưu trữ','Storage','green'],['database','Cơ sở dữ liệu','Database','purple'],['network','Mạng & phân phối','Networking','blue'],['security','Bảo mật & danh tính','Security','red'],['integration','Tích hợp ứng dụng','Integration','pink'],['analytics','Phân tích dữ liệu','Analytics','teal'],['governance','Quản trị & giám sát','Governance','indigo'],['migration','Di chuyển & hybrid','Migration','yellow'],['cost','Tối ưu chi phí','Cost','gray']
];
// id | name | category | short | definition | mechanics | use case | caution | related | AWS product slug
const rows = [
['ec2','Amazon EC2','compute','Máy chủ ảo, toàn quyền cấu hình','Dịch vụ cấp máy chủ ảo (instance) để chạy hệ điều hành và ứng dụng. Bạn chọn cấu hình CPU, RAM, mạng và ổ đĩa; AWS quản lý phần cứng, bạn quản lý hệ điều hành, bản vá và ứng dụng.','AMI là khuôn máy; instance type quyết định tài nguyên; user data chạy cấu hình khi khởi tạo. Instance nằm trong một subnet, một AZ. Gắn IAM role để nhận quyền tạm thời và security group để lọc kết nối.','Ứng dụng cần quyền quản trị OS, phần mềm truyền thống, web server hoặc tác vụ tính toán dài. Ví dụ: ALB nhận HTTPS và chuyển tới EC2 trong private subnet.','Stop/start có thể đổi public IPv4 tự cấp. Instance store là lưu trữ tạm. Spot có thể bị thu hồi; chỉ chọn khi workload chịu được gián đoạn.','ebs,asg,elb,vpc,iam','ec2'],
['asg','EC2 Auto Scaling','compute','Tự điều chỉnh số lượng EC2','Nhóm quản lý một tập EC2, giữ số lượng máy mong muốn và thay thế máy không khỏe. Mở rộng ngang giúp đáp ứng tải mà không phải nâng cấu hình từng máy.','Launch template định nghĩa cách tạo instance. Min, desired và max giới hạn quy mô; target tracking theo dõi một chỉ số mục tiêu. Phân bổ nhóm qua nhiều AZ và bật ELB health checks khi cần kiểm tra ứng dụng.','Web có lưu lượng biến động; worker SQS mở rộng theo backlog trên mỗi instance. Kết hợp ALB để gửi yêu cầu đến các máy khỏe.','Auto Scaling không tự làm ứng dụng stateless. Lưu session ngoài máy và tính đến thời gian khởi động; scaling không xử lý tức thì mọi đợt tăng tải.','ec2,elb,cloudwatch,sqs,efs','ec2/autoscaling'],
['lambda','AWS Lambda','compute','Chạy hàm theo sự kiện','Nền tảng chạy code mà không quản lý máy chủ. Mỗi invocation xử lý một yêu cầu hay sự kiện; phù hợp tác vụ ngắn, độc lập và có khả năng chạy song song.','Trigger có thể là API Gateway, S3 hoặc event source mapping đọc SQS và Kinesis. Execution role cấp quyền; memory ảnh hưởng tài nguyên CPU. Concurrency là số invocation cùng chạy.','Xử lý ảnh mới tải lên S3, API serverless, chuyển đổi thông điệp hoặc tác vụ tự động phản ứng với EventBridge.','Một invocation tối đa 15 phút. Thiết kế idempotent vì sự kiện có thể được giao lại. Gắn VPC không tự cung cấp Internet; truy cập Internet từ private subnet thường cần NAT.','apigateway,dynamodb,sqs,eventbridge,s3,iam','lambda'],
['ecs','Amazon ECS','compute','Điều phối container theo task','Dịch vụ điều phối container do AWS quản lý. Task definition mô tả image, tài nguyên, cổng và role; service giữ số task mong muốn hoạt động.','Chạy task trên EC2 do bạn quản lý hoặc Fargate do AWS quản lý hạ tầng. ECS service có thể đăng ký task vào target group của ALB; ECR lưu container image.','Microservices và ứng dụng đóng gói Docker muốn tích hợp sâu IAM, ALB và CloudWatch mà không cần Kubernetes.','ECS là bộ điều phối; Fargate là năng lực chạy container. Task role cấp quyền cho code; task execution role phục vụ các thao tác như kéo image và gửi log.','fargate,ecr,elb,cloudwatch,iam','ecs'],
['eks','Amazon EKS','compute','Kubernetes được quản lý','Dịch vụ Kubernetes có control plane được AWS quản lý. Bạn triển khai workload bằng Kubernetes API, phù hợp hệ thống đã chuẩn hóa công cụ và kỹ năng Kubernetes.','Pod chạy trên các lựa chọn compute được hỗ trợ như managed node group hoặc Fargate. Cần thiết kế networking, quyền của workload và capacity; control plane được quản lý không đồng nghĩa mọi cấu hình ứng dụng tự vận hành.','Chuyển ứng dụng Kubernetes lên AWS hoặc dùng hệ sinh thái Kubernetes, Helm và operator.','Độ phức tạp vận hành cao hơn mô hình task đơn giản. Phân biệt IAM dùng truy cập AWS với RBAC dùng cấp quyền trong Kubernetes.','ec2,fargate,ecr,vpc,iam','eks'],
['fargate','AWS Fargate','compute','Compute serverless cho container','Cơ chế chạy container cho ECS và EKS mà không cấp hay vá EC2 worker. Bạn khai báo tài nguyên cho workload và AWS vận hành máy chạy bên dưới.','Chọn CPU và RAM trong cấu hình được hỗ trợ, cấu hình subnet và security group. Với ECS, mỗi task có giao diện mạng riêng theo awsvpc.','API container, worker hoặc batch container khi muốn giảm công việc quản lý máy chủ.','Không thay thế ECS hay EKS; cần bộ điều phối. Kiểm tra giới hạn tính năng và chi phí với workload chạy liên tục; không mặc định rẻ hơn EC2.','ecs,eks,ecr,vpc','fargate'],
['ecr','Amazon ECR','compute','Kho container image','Registry lưu và phân phối container image riêng hoặc công khai. Image được định danh bằng tag hoặc digest và được ECS, EKS hay pipeline kéo về khi triển khai.','Đẩy image từ pipeline; dùng IAM và repository policy để kiểm soát truy cập. Lifecycle policy dọn image cũ; tính năng scanning hỗ trợ phát hiện lỗ hổng.','Lưu image cho microservices và quản lý phiên bản triển khai.','ECR lưu image, không chạy container. Dùng digest khi cần cố định chính xác phiên bản thay vì tag có thể bị ghi đè.','ecs,eks,iam','ecr'],
['beanstalk','Elastic Beanstalk','compute','Triển khai ứng dụng trên hạ tầng quản lý sẵn','Dịch vụ triển khai ứng dụng web bằng cách tạo và điều phối các tài nguyên như EC2, Auto Scaling và load balancer. Bạn đưa code, chọn platform và cấu hình môi trường.','Environment đóng gói các tài nguyên; hỗ trợ nhiều chiến lược deployment. Bạn vẫn có thể điều chỉnh cấu hình hạ tầng bên dưới.','Đội phát triển muốn triển khai web nhanh và vẫn cần môi trường EC2.','Không phải Lambda: vẫn có máy chủ và chi phí tài nguyên nền. Tách cơ sở dữ liệu lâu dài khỏi vòng đời môi trường ứng dụng.','ec2,asg,elb,rds','elasticbeanstalk'],
['batch','AWS Batch','compute','Lập lịch xử lý theo lô','Dịch vụ xếp hàng và lập lịch các job container lên năng lực compute phù hợp. Hữu ích khi công việc hữu hạn cần thực hiện hàng loạt thay vì phục vụ request liên tục.','Job definition mô tả container; job queue nhận công việc; compute environment cung cấp tài nguyên như EC2 hoặc Fargate.','Render, mô phỏng, xử lý tệp lớn hoặc job tính toán vượt thời gian chạy của Lambda.','Batch điều phối công việc, không phải công cụ ETL trực quan. Spot phù hợp khi job có thể retry hoặc checkpoint.','ec2,fargate,s3','batch'],
['s3','Amazon S3','storage','Lưu trữ đối tượng theo bucket và key','Object storage lưu dữ liệu thành object trong bucket, truy cập qua API. Phù hợp file, ảnh, backup và data lake; không phải ổ đĩa block hay hệ thống file POSIX để gắn trực tiếp cho mọi ứng dụng.','Bucket thuộc một Region. Versioning giữ các phiên bản; lifecycle chuyển lớp lưu trữ hoặc hết hạn. Bucket policy, IAM và Block Public Access kiểm soát truy cập. Replication cần cấu hình riêng.','Website tĩnh qua CloudFront, nhận file tải lên bằng presigned URL, lưu log và dữ liệu phân tích.','S3 có strong consistency cho thao tác đọc/ghi object. Durability không thay thế backup chống xóa nhầm. Website endpoint không dùng OAC; muốn bucket private, dùng REST origin với CloudFront OAC.','cloudfront,kms,lambda,athena,glacier','s3'],
['ebs','Amazon EBS','storage','Ổ đĩa block cho EC2','Block storage bền vững dùng làm boot volume hoặc data volume cho EC2. Ứng dụng thấy thiết bị block và có thể tạo filesystem trên đó.','Volume nằm trong một AZ, gắn với EC2 cùng AZ. Snapshot là bản sao point-in-time để khôi phục volume, kể cả ở AZ khác. Chọn loại volume theo IOPS, throughput và chi phí.','Cơ sở dữ liệu tự quản trên EC2, ổ hệ điều hành hoặc ứng dụng cần ổ đĩa độ trễ thấp.','Không mặc định chia sẻ một volume cho nhiều máy. Multi-Attach chỉ áp dụng một số loại và yêu cầu ứng dụng/filesystem phù hợp. Tùy chọn DeleteOnTermination quyết định xóa volume khi terminate.','ec2,backup,kms','ebs'],
['efs','Amazon EFS','storage','File system NFS dùng chung','Dịch vụ hệ thống file co giãn cho workload Linux, có thể được nhiều client truy cập đồng thời qua NFS. Dùng khi ứng dụng cần đường dẫn và thao tác file dùng chung.','Mount target cung cấp điểm truy cập trong VPC. Regional EFS lưu dữ liệu qua nhiều AZ; One Zone là lựa chọn khác. Access point hỗ trợ phân tách đường dẫn và danh tính POSIX.','CMS hoặc nhóm EC2 Auto Scaling cần chia sẻ thư mục; Lambda cần dữ liệu filesystem bền vững.','Security group phải cho phép NFS phù hợp. Regional và One Zone có đặc tính chịu lỗi khác nhau; không chọn One Zone nếu yêu cầu chịu mất AZ.','ec2,lambda,asg,backup,vpc','efs'],
['fsx','Amazon FSx','storage','File system chuyên dụng được quản lý','Họ dịch vụ file system theo nhu cầu cụ thể: Windows File Server, Lustre, NetApp ONTAP và OpenZFS. Chọn loại theo giao thức và tính năng ứng dụng cần.','Windows File Server hỗ trợ SMB và tích hợp Active Directory. Lustre phù hợp tính toán hiệu năng cao và tích hợp S3. Các loại có cấu hình availability và backup khác nhau.','Windows file share → FSx for Windows; HPC/ML xử lý tập dữ liệu lớn → FSx for Lustre.','FSx không phải một filesystem duy nhất. SMB, NFS, hiệu năng, Multi-AZ và khả năng tích hợp phụ thuộc loại được chọn.','s3,ec2,directoryservice,backup','fsx'],
['glacier','S3 Glacier storage classes','storage','Lưu trữ lưu trữ dài hạn','Các lớp S3 dành cho dữ liệu ít truy cập: Glacier Instant Retrieval, Flexible Retrieval và Deep Archive. Đây là lựa chọn lớp lưu trữ object theo yêu cầu truy xuất và thời gian lưu.','Instant Retrieval cho truy cập tức thì; Flexible Retrieval và Deep Archive cần restore trước khi đọc theo quy trình thông thường. Lifecycle tự chuyển dữ liệu theo tuổi object.','Lưu hồ sơ pháp lý, bản sao lâu dài và dữ liệu lịch sử ít được dùng.','Không chọn chỉ theo giá GB. Tính thêm phí truy xuất, thời gian lưu tối thiểu và độ trễ khôi phục. Deep Archive không phù hợp phục hồi cần dữ liệu ngay.','s3,backup','s3/storage-classes/glacier'],
['backup','AWS Backup','storage','Chính sách sao lưu tập trung','Dịch vụ lập lịch, lưu giữ và quản lý backup cho các tài nguyên AWS được hỗ trợ. Tách chính sách bảo vệ dữ liệu khỏi thao tác sao lưu thủ công từng dịch vụ.','Backup plan chỉ định lịch và retention; resource assignment chọn tài nguyên bằng ARN hoặc tag. Backup vault lưu recovery point; có thể cấu hình sao chép liên tài khoản/Region khi được hỗ trợ.','Quản lý backup thống nhất cho EBS, RDS, EFS và các tài khoản trong Organizations.','Backup không phải failover đang chạy. Phải thử restore và kiểm tra RPO/RTO thực tế; quyền xóa và Vault Lock cần được thiết kế riêng.','ebs,efs,rds,organizations','backup'],
['storagegateway','AWS Storage Gateway','storage','Cầu nối lưu trữ tại chỗ với AWS','Dịch vụ hybrid cho ứng dụng tại chỗ truy cập lưu trữ được hỗ trợ bởi AWS thông qua các giao diện quen thuộc như file, volume hoặc virtual tape.','S3 File Gateway cung cấp NFS/SMB và lưu object vào S3; Volume Gateway cung cấp iSCSI; Tape Gateway cung cấp thư viện băng ảo. Cache cục bộ giảm độ trễ truy cập.','Giữ ứng dụng hoặc phần mềm backup tại datacenter nhưng mở rộng nơi lưu dữ liệu sang AWS.','Gateway là truy cập hybrid liên tục; DataSync chủ yếu truyền dữ liệu. Xem giới hạn dung lượng cache, đường truyền và chế độ gateway cụ thể.','s3,glacier,datasync','storagegateway'],
['rds','Amazon RDS','database','Cơ sở dữ liệu quan hệ được quản lý','Dịch vụ vận hành database quan hệ với các engine được hỗ trợ. AWS xử lý nhiều công việc như provisioning, backup và bảo trì; bạn vẫn quản lý schema, query và quyền dữ liệu.','Multi-AZ DB instance dùng standby để failover. Read replica thường sao chép bất đồng bộ để scale đọc. Backup tự động hỗ trợ khôi phục theo thời điểm trong thời gian lưu đã cấu hình.','Ứng dụng giao dịch, đơn hàng và nghiệp vụ cần SQL, quan hệ và transaction.','Multi-AZ DB instance standby không phục vụ đọc; Multi-AZ DB cluster có reader đọc được. Read replica không mặc định đồng nghĩa high availability tự failover.','aurora,elb,secretsmanager,kms,dms','rds'],
['aurora','Amazon Aurora','database','Database quan hệ với storage phân tán','Database trong họ RDS, tương thích MySQL hoặc PostgreSQL, tách compute khỏi storage phân tán. Hướng tới hệ thống giao dịch cần availability và scale đọc.','Cluster có writer và có thể có reader. Cluster endpoint theo writer; reader endpoint phân phối kết nối đọc. Aurora Serverless v2 điều chỉnh compute trong dải cấu hình; Global Database phục vụ kiến trúc nhiều Region.','Hệ thống SQL cần nhiều bản sao đọc, failover nhanh hoặc khôi phục thảm họa liên Region.','Reader endpoint cân bằng kết nối, không phải từng truy vấn. Tương thích engine không có nghĩa mọi extension hay phiên bản đều hỗ trợ.','rds,secretsmanager,kms,dms','rds/aurora'],
['dynamodb','Amazon DynamoDB','database','NoSQL key-value và document','Database serverless cho truy cập theo khóa với độ trễ thấp. Thiết kế dựa trên access pattern: biết cần đọc gì trước khi chọn partition key, sort key và index.','Partition key phân tán dữ liệu; sort key sắp xếp trong cùng partition. On-demand hoặc provisioned điều khiển capacity. Streams ghi thay đổi để downstream xử lý; Global Tables sao chép đa Region.','Giỏ hàng, hồ sơ người dùng, trạng thái ứng dụng hoặc workload lớn truy cập theo key.','Không phải SQL với join tùy ý. Hot partition có thể làm nghẽn dù tổng capacity đủ. GSI chỉ hỗ trợ eventually consistent reads; consistency và xung đột đa Region phụ thuộc chế độ Global Tables.','lambda,apigateway,kms','dynamodb'],
['elasticache','Amazon ElastiCache','database','Cache trong bộ nhớ','Dịch vụ cache in-memory với các engine được hỗ trợ như Valkey, Redis OSS và Memcached. Đưa dữ liệu thường đọc gần ứng dụng giúp giảm tải database và giảm độ trễ.','Cache-aside: ứng dụng đọc cache, khi miss thì đọc database rồi nạp cache. TTL và cơ chế invalidation quyết định độ mới dữ liệu; replication và failover tùy engine/cấu hình.','Session dùng chung, bảng xếp hạng, cache query hoặc dữ liệu sản phẩm phổ biến.','Cache miss vẫn cần nguồn dữ liệu. Tránh coi cache là bản lưu bền duy nhất khi kiến trúc chưa đảm bảo durability; cân nhắc stale data và cache stampede.','rds,aurora,ec2,ecs','elasticache'],
['neptune','Amazon Neptune','database','Database cho dữ liệu đồ thị','Database được quản lý tối ưu lưu node và quan hệ giữa chúng. Phù hợp khi truy vấn tập trung đi qua nhiều kết nối thay vì join bảng theo cách thông thường.','Mô hình graph biểu diễn thực thể và cạnh; chọn mô hình và ngôn ngữ truy vấn được hỗ trợ cho workload.','Phát hiện gian lận, mạng xã hội, knowledge graph hoặc gợi ý dựa trên quan hệ.','Graph là mô hình dữ liệu; không chọn chỉ vì dữ liệu có vài quan hệ đơn giản mà SQL đã đáp ứng tốt.','s3,vpc,iam','neptune'],
['documentdb','Amazon DocumentDB','database','Database tài liệu JSON','Database được quản lý với khả năng tương thích MongoDB, dành cho ứng dụng lưu và truy vấn document. Document gom các thuộc tính liên quan thành cấu trúc lồng nhau.','Tách storage và compute; dùng instance chính cùng replica theo cấu hình cluster. Kiểm tra driver và API ứng dụng sử dụng trước migration.','Catalog, nội dung và hồ sơ có cấu trúc linh hoạt theo document.','Tương thích MongoDB không đồng nghĩa thay thế hoàn toàn mọi API hay hành vi của MongoDB. Cần kiểm thử tính năng thực tế.','dms,vpc,kms','documentdb'],
['vpc','Amazon VPC','network','Mạng riêng logic trong một Region','Không gian mạng cô lập để triển khai tài nguyên AWS với CIDR, subnet, route table và các lớp kiểm soát lưu lượng do bạn cấu hình. Một subnet chỉ thuộc một AZ.','Public subnet có route tới Internet Gateway; EC2 còn cần public IP để giao tiếp IPv4 trực tiếp với Internet. Private subnet có thể đi ra qua NAT. Security group stateful; network ACL stateless và gắn ở subnet.','Tách lớp web, ứng dụng và database; giới hạn database chỉ nhận kết nối từ security group ứng dụng.','Gán public IP chưa đủ nếu thiếu route hoặc rule. Security group chỉ có allow; NACL có allow/deny và phải cho return traffic. Peering không có định tuyến bắc cầu.','nat,privatelink,elb,ec2,rds','vpc'],
['nat','NAT Gateway','network','Cho private subnet đi ra Internet','Thành phần NAT được quản lý, cho tài nguyên dùng private IPv4 khởi tạo kết nối ra ngoài trong cấu hình public NAT thông dụng. Không cho Internet tự mở kết nối vào máy private.','Public NAT Gateway đặt trong public subnet, có Elastic IP và đường tới Internet Gateway. Route của private subnet trỏ Internet-bound traffic đến NAT.','EC2 private cần tải bản vá hoặc gọi API bên ngoài mà không nhận kết nối vào trực tiếp.','NAT không phải bastion host hay firewall ứng dụng. Để chịu lỗi AZ, thường bố trí NAT theo AZ và route phù hợp; có phí giờ và xử lý dữ liệu.','vpc,privatelink,ec2','vpc'],
['privatelink','VPC endpoints & PrivateLink','network','Truy cập dịch vụ qua đường private','VPC endpoint tạo đường truy cập dịch vụ được hỗ trợ mà không cần Internet Gateway hay NAT cho luồng đó. Có gateway endpoint và interface endpoint với cơ chế khác nhau.','Gateway endpoint cho S3/DynamoDB dùng route table. Interface endpoint dùng ENI, private IP và security group, dựa trên PrivateLink. Private DNS cho phép tên miền dịch vụ phân giải về endpoint private.','EC2 private truy cập S3 bằng gateway endpoint; gọi Secrets Manager bằng interface endpoint.','Không nhầm gateway endpoint với Gateway Load Balancer endpoint. PrivateLink không biến mọi VPC thành mạng định tuyến đầy đủ; endpoint policy cũng không tự cấp quyền IAM.','vpc,s3,dynamodb,secretsmanager','privatelink'],
['elb','Elastic Load Balancing','network','Phân phối lưu lượng tới các target','Họ load balancer phân phối traffic và kiểm tra sức khỏe target. ALB phù hợp HTTP/HTTPS với routing lớp 7; NLB phục vụ lớp 4 như TCP/UDP/TLS; GWLB cho thiết bị mạng.','Listener nhận kết nối; rule quyết định target group; health check loại target lỗi. ALB hỗ trợ host/path routing. Kết hợp Auto Scaling để vừa phân phối tải vừa tăng số máy.','ALB cho microservices theo đường dẫn; NLB khi cần IP tĩnh hoặc TCP; GWLB cho chuỗi appliance bảo mật.','Load balancer không tự tạo thêm EC2. Database không nên bị public chỉ để tiện truy cập; cấu hình security group theo luồng thực tế.','asg,ec2,ecs,acm,waf','elasticloadbalancing'],
['route53','Amazon Route 53','network','DNS, routing và health check','Dịch vụ DNS authoritative, đăng ký tên miền và kiểm tra sức khỏe. Chuyển tên miền thành endpoint theo policy phù hợp kiến trúc.','Hosted zone chứa record. Alias trỏ tới một số tài nguyên AWS; weighted chia tỷ lệ, latency chọn theo độ trễ, failover chọn primary/secondary. Resolver hỗ trợ DNS hybrid.','Trỏ tên miền tới ALB/CloudFront, chia traffic khi chuyển phiên bản hoặc failover giữa endpoint.','DNS không proxy request của người dùng. TTL và DNS cache ảnh hưởng thời gian chuyển hướng; health check endpoint private cần thiết kế khác với public endpoint.','cloudfront,elb,globalaccelerator','route53'],
['cloudfront','Amazon CloudFront','network','CDN phân phối nội dung ở edge','Mạng phân phối nội dung cache dữ liệu gần người dùng và chuyển request về origin khi cần. Origin có thể là S3 REST endpoint, ALB hoặc HTTP server.','Cache behavior chọn origin và policy theo path. Cache key, TTL, cookie và query string ảnh hưởng hit ratio. OAC kiểm soát truy cập origin S3; WAF và ACM bổ sung bảo vệ.','Website tĩnh S3 private, phân phối ảnh/video và tăng tốc nội dung web toàn cầu.','Không phải mọi request đều cache; API động cần policy phù hợp. Chứng chỉ ACM dùng với CloudFront phải ở us-east-1. Không công khai bucket chỉ để CDN đọc.','s3,route53,waf,acm,elb','cloudfront'],
['globalaccelerator','AWS Global Accelerator','network','IP anycast tĩnh và mạng backbone AWS','Dịch vụ đưa traffic TCP/UDP từ edge vào mạng toàn cầu AWS và định tuyến tới endpoint khỏe ở các Region. Phù hợp tăng tính ổn định truy cập ứng dụng toàn cầu.','Cung cấp địa chỉ IP anycast tĩnh; endpoint group chứa ALB, NLB hoặc endpoint được hỗ trợ. Traffic dial và health check điều chỉnh hướng traffic.','Ứng dụng đa Region cần IP để allowlist, game hoặc traffic TCP/UDP độ trễ nhạy cảm.','Không cache nội dung như CloudFront. Lựa chọn giữa DNS routing, CDN và accelerator phụ thuộc giao thức, caching và yêu cầu IP tĩnh.','elb,route53,ec2','global-accelerator'],
['transitgateway','AWS Transit Gateway','network','Hub kết nối nhiều mạng','Bộ định tuyến trung tâm kết nối nhiều VPC và mạng tại chỗ. Giảm số kết nối point-to-point khi số VPC lớn.','VPC/VPN attachment kết nối tới hub; route table kiểm soát các nhóm mạng nào liên lạc được với nhau. Có thể kết hợp Direct Connect qua kiến trúc gateway phù hợp.','Mạng doanh nghiệp nhiều tài khoản và VPC muốn quản lý định tuyến tập trung.','Kết nối attachment chưa đủ: cần route ở cả VPC lẫn Transit Gateway. Phải tránh CIDR chồng lấn và xem phí xử lý lưu lượng.','vpc,vpn,directconnect,organizations','transit-gateway'],
['vpn','AWS Site-to-Site VPN','network','Đường hầm IPsec qua Internet','Kết nối mạng tại chỗ tới AWS bằng tunnel IPsec mã hóa. Thường nhanh triển khai hơn đường truyền chuyên dụng.','Customer gateway mô tả phía datacenter; phía AWS dùng virtual private gateway hoặc Transit Gateway. Một kết nối cung cấp hai tunnel để thiết kế dự phòng.','Hybrid network, kết nối dự phòng hoặc nhu cầu triển khai đường truyền mã hóa nhanh.','Chất lượng phụ thuộc đường Internet. Hai tunnel không có nghĩa mọi thiết bị và đường truyền phía khách hàng đã hết single point of failure.','vpc,transitgateway,directconnect','vpn'],
['directconnect','AWS Direct Connect','network','Đường kết nối chuyên dụng tới AWS','Dịch vụ kết nối mạng riêng từ cơ sở của bạn tới địa điểm Direct Connect, cung cấp đường truyền với tính ổn định phù hợp hybrid enterprise.','Virtual interface phân tách kết nối tới tài nguyên private hoặc dịch vụ public. Có thể kết hợp Direct Connect gateway và Transit Gateway theo quy mô.','Truyền dữ liệu đều đặn dung lượng lớn hoặc hệ thống hybrid cần băng thông và độ trễ ổn định hơn Internet.','Không mặc định mã hóa traffic. Thiết kế mã hóa bổ sung và kết nối dự phòng; một đường Direct Connect đơn lẻ không đảm bảo khả năng chịu lỗi toàn hệ thống.','vpn,transitgateway,vpc','directconnect'],
['iam','AWS IAM','security','Ai được làm gì với tài nguyên nào','Hệ thống xác thực và phân quyền truy cập AWS. Policy JSON quy định action, resource, effect và condition; áp dụng nguyên tắc least privilege.','User là danh tính; role được assume để nhận credential tạm thời qua STS. Identity policy, resource policy, boundary và SCP tham gia đánh giá quyền theo ngữ cảnh; explicit deny có ưu tiên.','Gán role cho EC2/Lambda để truy cập S3 mà không nhúng access key. Bật MFA và bảo vệ root user.','Role trust policy quyết định ai được assume, permission policy quyết định role được làm gì. SCP và permission boundary giới hạn quyền, không tự cấp quyền.','organizations,kms,ec2,lambda,s3','iam'],
['kms','AWS KMS','security','Quản lý khóa mã hóa','Dịch vụ quản lý cryptographic key, kiểm soát việc sử dụng khóa và tích hợp mã hóa với nhiều dịch vụ AWS. Hữu ích khi cần audit và phân quyền khóa tập trung.','Envelope encryption: data key mã hóa dữ liệu, KMS key bảo vệ data key. Key policy và IAM policy điều khiển truy cập; CloudTrail ghi hoạt động API.','SSE-KMS cho S3, mã hóa EBS/RDS hoặc dữ liệu ứng dụng cần kiểm soát khóa.','Quyền đọc object S3 không tự đảm bảo quyền kms:Decrypt. Xóa key có thể làm dữ liệu không giải mã được; rotation không tự mã hóa lại mọi dữ liệu cũ.','s3,ebs,rds,secretsmanager,cloudtrail','kms'],
['secretsmanager','AWS Secrets Manager','security','Lưu và luân chuyển bí mật','Dịch vụ lưu password, API token và thông tin nhạy cảm, truy xuất qua API có phân quyền thay vì hardcode trong code.','Secret được mã hóa bằng KMS. Hỗ trợ rotation cho các tích hợp phù hợp, có thể dùng Lambda cho quy trình tùy chỉnh; ứng dụng nên cache có kiểm soát.','Lưu credential RDS và tự động thay đổi định kỳ.','Rotation cần cấu hình và quyền đúng, không tự hoạt động cho mọi secret. Parameter Store phù hợp cấu hình và SecureString khi không cần đầy đủ tính năng quản lý secret.','kms,rds,lambda,ssm','secrets-manager'],
['acm','AWS Certificate Manager','security','Cấp và quản lý chứng chỉ TLS','Dịch vụ quản lý chứng chỉ để mã hóa kết nối HTTPS/TLS với các dịch vụ được hỗ trợ. Giảm việc vận hành vòng đời chứng chỉ thủ công.','Xác thực quyền sở hữu domain; gắn certificate vào ALB hoặc CloudFront. Managed renewal phụ thuộc loại chứng chỉ và điều kiện sử dụng/xác thực.','HTTPS cho website và API, TLS termination trên ALB.','Chứng chỉ có phạm vi Region; CloudFront dùng ACM ở us-east-1. TLS bảo vệ khi truyền dữ liệu, không thay thế mã hóa dữ liệu lưu trữ bằng KMS.','elb,cloudfront,route53','certificate-manager'],
['waf','AWS WAF','security','Lọc request web ở lớp ứng dụng','Web application firewall đánh giá HTTP request bằng các rule như IP, header, rate và mẫu tấn công. Giúp hạn chế SQL injection, XSS và traffic không mong muốn.','Web ACL chứa rule/managed rule và được gắn vào tài nguyên được hỗ trợ như CloudFront, ALB hoặc API Gateway REST API. Rate-based rule giới hạn theo điều kiện cấu hình.','Bảo vệ API, chặn IP và lọc request web theo tiêu chí ứng dụng.','WAF không vá lỗ hổng code và không phải security group cho TCP/UDP. Cần theo dõi false positive trước khi bật block rộng.','cloudfront,elb,apigateway,shield','waf'],
['shield','AWS Shield','security','Bảo vệ trước tấn công DDoS','Dịch vụ bảo vệ tính sẵn sàng trước distributed denial-of-service. Shield Standard được cung cấp tự động; Advanced bổ sung các tính năng bảo vệ và hỗ trợ có điều kiện.','Kết hợp edge của AWS, phát hiện và giảm thiểu DDoS. CloudFront, Route 53 và thiết kế ứng dụng co giãn góp phần giảm bề mặt tấn công.','Website hoặc ứng dụng Internet cần chống làm cạn tài nguyên bởi traffic tấn công.','Phân biệt DDoS mạng với lọc nội dung request của WAF. Không giả định mọi thiệt hại chi phí đều được hoàn trả; kiểm tra điều kiện của gói dùng thực tế.','waf,cloudfront,route53','shield'],
['cognito','Amazon Cognito','security','Đăng nhập cho người dùng ứng dụng','Dịch vụ danh tính cho ứng dụng web/mobile, hỗ trợ đăng ký, đăng nhập và federation. Phù hợp khách hàng ứng dụng thay vì tạo IAM user cho mỗi khách hàng.','User pool quản lý user và phát token. Identity pool đổi danh tính được chấp nhận thành credential AWS tạm thời theo role. Tích hợp API authorizer để xác minh token.','Ứng dụng khách hàng đăng nhập rồi gọi API hoặc tải file lên S3 với quyền giới hạn.','User pool và identity pool giải quyết hai việc khác nhau. Xác thực thành công vẫn cần authorization đúng tài nguyên và tenant.','apigateway,iam,s3','cognito'],
['guardduty','Amazon GuardDuty','security','Phát hiện hành vi đe dọa','Dịch vụ threat detection phân tích các nguồn telemetry được hỗ trợ để tìm hành vi đáng ngờ trong tài khoản và workload. Kết quả là security finding để điều tra.','Phân tích dấu hiệu bất thường và threat intelligence; protection plan mở rộng phạm vi theo workload. Đẩy finding sang EventBridge cho quy trình phản ứng.','Phát hiện credential bị lạm dụng hoặc hoạt động mạng đáng ngờ.','Không phải công cụ vá máy và không tự chặn mọi mối đe dọa. Cần quy trình xác minh và remediation.','eventbridge,cloudtrail,securityhub','guardduty'],
['inspector','Amazon Inspector','security','Tìm lỗ hổng trong workload','Dịch vụ quản lý lỗ hổng cho các tài nguyên được hỗ trợ, như EC2, container image trong ECR và Lambda theo loại scanning.','Đánh giá package và exposure trong phạm vi cấu hình; phát finding có mức độ ưu tiên để đội vận hành khắc phục.','Quét image trước hoặc sau triển khai và theo dõi lỗ hổng máy chủ.','Inspector tìm vulnerability; GuardDuty tìm dấu hiệu đe dọa. Có finding không có nghĩa hệ thống tự được cập nhật bản vá.','ec2,ecr,lambda,securityhub','inspector'],
['macie','Amazon Macie','security','Phát hiện dữ liệu nhạy cảm trong S3','Dịch vụ giúp nhận diện dữ liệu nhạy cảm và rủi ro bảo vệ dữ liệu trong Amazon S3. Tập trung vào dữ liệu và quyền truy cập bucket.','Phân tích theo job hoặc cơ chế discovery được hỗ trợ; dùng managed/custom data identifier để phát hiện mẫu như thông tin cá nhân.','Rà soát bucket chứa hồ sơ khách hàng hoặc dữ liệu cần kiểm soát riêng tư.','Không phải antivirus cho mọi storage và không tự mã hóa hoặc xóa dữ liệu đã phát hiện.','s3,securityhub,eventbridge','macie'],
['securityhub','AWS Security Hub','security','Tập hợp và đánh giá bảo mật','Dịch vụ tập trung security finding và hỗ trợ đánh giá trạng thái bảo mật theo các khả năng, tiêu chuẩn và tích hợp được bật.','Tổng hợp kết quả từ GuardDuty, Inspector, Macie và nguồn được hỗ trợ; quy trình xử lý dùng automation và EventBridge khi thích hợp.','Một nơi theo dõi các phát hiện bảo mật thay vì mở từng dịch vụ riêng lẻ.','Tổng hợp finding không thay thế các engine phát hiện chuyên biệt. Kiểm tra các tính năng được bật, quyền và Region khi triển khai.','guardduty,inspector,macie,config,eventbridge','security-hub'],
['directoryservice','AWS Directory Service','security','Danh bạ và Active Directory','Các lựa chọn danh bạ được quản lý và tích hợp danh tính doanh nghiệp. AWS Managed Microsoft AD cung cấp Microsoft Active Directory được quản lý; AD Connector chuyển yêu cầu về AD hiện có.','Tích hợp ứng dụng cần domain, group policy hoặc cơ chế xác thực AD; có thể thiết lập trust với directory tại chỗ khi phù hợp.','FSx for Windows File Server và workload Windows cần Active Directory.','AD Connector không phải bản sao AD được lưu trên AWS. Phân biệt danh bạ doanh nghiệp với Cognito cho người dùng ứng dụng.','fsx,vpc,vpn','directoryservice'],
['sqs','Amazon SQS','integration','Hàng đợi tách producer và consumer','Message queue được quản lý để các thành phần trao đổi công việc bất đồng bộ. Producer gửi message; consumer lấy, xử lý rồi xóa khi thành công.','Visibility timeout tạm ẩn message khi đang xử lý. Standard có at-least-once delivery và best-effort ordering. FIFO hỗ trợ thứ tự trong message group và deduplication. DLQ giữ message xử lý lỗi quá số lần quy định.','Hấp thụ đột biến đơn hàng, tách web khỏi worker và retry công việc nền.','Visibility timeout không phải retention. Consumer phải idempotent; ngay cả FIFO cũng không biến mọi side effect bên ngoài thành exactly-once.','lambda,sns,asg,kms','sqs'],
['sns','Amazon SNS','integration','Phát một thông báo tới nhiều nơi','Dịch vụ publish/subscribe: publisher gửi vào topic, SNS phân phối tới nhiều subscriber. Hữu ích cho fan-out sự kiện.','Subscriber có thể là SQS, Lambda và các endpoint được hỗ trợ. Subscription filter chọn message cần nhận; kết hợp từng queue cho từng nhóm consumer.','Một đơn hàng mới kích hoạt riêng nhóm gửi email, kho hàng và phân tích bằng SNS → nhiều SQS.','SNS không thay thế queue lưu backlog độc lập. Mỗi nhóm cần xử lý và retry riêng thường nên có SQS phía sau.','sqs,lambda,cloudwatch','sns'],
['eventbridge','Amazon EventBridge','integration','Định tuyến sự kiện theo nội dung','Event bus nhận sự kiện từ ứng dụng, AWS hoặc nguồn tích hợp và định tuyến tới target theo rule. Hướng tới giao tiếp giữa hệ thống theo sự kiện.','Event pattern lọc trường trong payload; target nhận sự kiện phù hợp. Có các tính năng như Scheduler, archive/replay và Pipes theo nhu cầu tích hợp.','Khi trạng thái đơn hàng đổi, định tuyến tới các luồng xử lý khác nhau; tự động phản ứng với finding bảo mật.','Không đảm bảo thứ tự toàn cục. Retry, DLQ và idempotency phải được thiết kế; stream replay có thứ tự theo shard là bài toán của Kinesis.','lambda,sqs,stepfunctions,guardduty','eventbridge'],
['stepfunctions','AWS Step Functions','integration','Điều phối workflow có trạng thái','Dịch vụ mô tả quy trình nhiều bước bằng state machine, hỗ trợ nhánh, chạy song song, retry và xử lý lỗi mà không nhét toàn bộ điều phối vào một hàm.','State gọi Lambda hoặc tích hợp dịch vụ khác. Standard và Express có đặc điểm thời lượng, lịch sử và execution semantics khác nhau; chọn theo yêu cầu workflow.','Xử lý đơn hàng: kiểm tra, thanh toán, cập nhật kho và bù trừ khi một bước thất bại.','Không phải message queue hoặc compute để chạy code tùy ý. Retry side effect như thanh toán phải có idempotency key.','lambda,sqs,eventbridge,dynamodb','step-functions'],
['apigateway','Amazon API Gateway','integration','Cửa vào API được quản lý','Dịch vụ tạo, xuất bản và kiểm soát HTTP/REST/WebSocket API. Nhận request từ client rồi chuyển tới backend hoặc tích hợp dịch vụ.','Route/method trỏ đến integration. Authorizer kiểm soát danh tính; throttling giới hạn request; logging và metrics giúp quan sát. Tính năng cụ thể khác nhau giữa REST API và HTTP API.','Backend serverless: client → API Gateway → Lambda → DynamoDB.','API key dùng quản lý usage không phải cơ chế xác thực an toàn thay cho IAM/Cognito/authorizer. Không mặc định mọi loại API đều hỗ trợ cùng caching và WAF.','lambda,cognito,dynamodb,cloudwatch,waf','api-gateway'],
['mq','Amazon MQ','integration','Message broker tương thích giao thức','Dịch vụ broker được quản lý cho ActiveMQ và RabbitMQ, phục vụ ứng dụng đang dựa vào giao thức và hành vi của các broker đó.','Broker xử lý queue, subscription và giao thức tương ứng. Kiểu triển khai và high availability phụ thuộc engine được chọn.','Di chuyển ứng dụng dùng JMS, AMQP hoặc hệ sinh thái broker hiện hữu với ít thay đổi code.','Ứng dụng mới cloud-native thường cân nhắc SQS/SNS; không mặc định đổi broker sang SQS mà giữ nguyên API ứng dụng.','sqs,sns,vpc','amazon-mq'],
['kinesis','Kinesis Data Streams','analytics','Luồng dữ liệu có khả năng đọc lại','Dịch vụ thu thập và lưu record streaming để nhiều consumer xử lý gần thời gian thực. Giữ dữ liệu trong khoảng retention đã cấu hình để đọc lại.','Partition key quyết định phân phối record; thứ tự có phạm vi shard. Consumer theo dõi vị trí đọc; chọn capacity mode theo workload.','Clickstream, telemetry, phát hiện bất thường và nhiều ứng dụng đọc cùng một nguồn event.','Không có thứ tự toàn stream khi nhiều shard. Phân biệt với SQS dùng xử lý công việc và Firehose dùng giao dữ liệu tới đích.','lambda,firehose,s3','kinesis/data-streams'],
['firehose','Amazon Data Firehose','analytics','Giao dữ liệu streaming tới kho đích','Dịch vụ nhận, đệm và giao dữ liệu streaming tới các đích được hỗ trợ. Giảm công việc tự viết consumer để tải dữ liệu vào kho lưu trữ/phân tích.','Buffer dữ liệu theo cấu hình; có thể biến đổi bằng Lambda, nén hoặc đổi định dạng trong các trường hợp hỗ trợ. S3 là đích thường dùng cho data lake.','Đưa log liên tục vào S3 rồi dùng Athena truy vấn.','Có buffering nên không mặc định độ trễ tức thì. Không thay thế stream có nhiều consumer độc lập cần replay theo offset.','kinesis,s3,lambda,athena,redshift','firehose'],
['athena','Amazon Athena','analytics','SQL serverless trên dữ liệu S3','Dịch vụ truy vấn dữ liệu bằng SQL mà không quản lý cluster cho mô hình truy vấn S3 thông dụng. Phù hợp phân tích ad hoc trên data lake.','Bảng mô tả schema và vị trí dữ liệu, thường dùng Glue Data Catalog. Partition, định dạng cột như Parquet và nén giúp giảm lượng dữ liệu scan.','Phân tích log, báo cáo sự kiện S3 và truy vấn điều tra không cần nạp vào database giao dịch.','Không phù hợp thay database OLTP cho thao tác đơn hàng từng bản ghi. SELECT * trên nhiều file lớn có thể tăng lượng scan và chi phí.','s3,glue,firehose','athena'],
['glue','AWS Glue','analytics','ETL và danh mục metadata','Dịch vụ tích hợp dữ liệu, có Data Catalog quản lý metadata và các công cụ xây dựng job ETL. Chuyển đổi dữ liệu giữa nguồn và đích để phục vụ phân tích.','Crawler phát hiện schema; catalog mô tả bảng, không lưu thay toàn bộ dữ liệu gốc. ETL job đọc, biến đổi và ghi dữ liệu theo lịch hoặc workflow.','Chuẩn hóa CSV/JSON sang Parquet, đăng ký bảng S3 cho Athena và chuẩn bị data lake.','Crawler không tự sửa mọi dữ liệu bẩn. Phân biệt metadata trong catalog với nội dung object thật ở S3.','s3,athena,redshift,lakeformation','glue'],
['redshift','Amazon Redshift','analytics','Kho dữ liệu cho phân tích SQL','Data warehouse cho truy vấn phân tích tổng hợp trên tập dữ liệu lớn. Tối ưu cho OLAP và báo cáo thay vì transaction nhỏ kiểu OLTP.','Lưu trữ dạng cột và xử lý song song; có lựa chọn provisioned và serverless. Có thể nạp dữ liệu S3 và truy vấn dữ liệu ngoài qua các khả năng phù hợp.','Báo cáo doanh thu nhiều năm, dashboard BI và phân tích doanh nghiệp.','RDS phù hợp đơn hàng giao dịch; Redshift phù hợp tổng hợp phân tích. Thiết kế dữ liệu và lượng compute vẫn ảnh hưởng mạnh đến hiệu năng và chi phí.','s3,glue,firehose','redshift'],
['emr','Amazon EMR','analytics','Xử lý big data với Spark/Hadoop','Nền tảng chạy framework big data như Apache Spark với các lựa chọn triển khai được hỗ trợ. Phù hợp khi cần kiểm soát framework và xử lý phân tán.','Job xử lý dữ liệu từ S3 hoặc nguồn khác; tách compute khỏi storage S3 giúp kết thúc compute sau khi xử lý.','Phân tích dữ liệu lớn, pipeline Spark hoặc chuyển hệ sinh thái Hadoop lên AWS.','Athena thích hợp truy vấn SQL ad hoc; Glue ETL được quản lý nhiều hơn. Chọn EMR khi nhu cầu framework và tùy chỉnh vận hành hợp lý.','s3,glue,ec2','emr'],
['opensearch','Amazon OpenSearch Service','analytics','Tìm kiếm và phân tích log','Dịch vụ triển khai tìm kiếm toàn văn và phân tích dữ liệu với OpenSearch cùng các lựa chọn được hỗ trợ. Tổ chức dữ liệu thành index để truy vấn và tổng hợp.','Ứng dụng hoặc pipeline đưa document vào index; query và dashboard hỗ trợ tìm kiếm, lọc và điều tra log.','Search sản phẩm, phân tích application log và quan sát hệ thống.','Không dùng như database giao dịch chính chỉ vì lưu được JSON. Phải thiết kế shard, retention và access control phù hợp kiểu triển khai.','firehose,s3,cloudwatch','opensearch-service'],
['lakeformation','AWS Lake Formation','analytics','Quản trị truy cập data lake','Dịch vụ thiết lập và quản lý quyền dữ liệu tập trung cho data lake, tích hợp Glue Data Catalog và các engine phân tích được hỗ trợ.','Cấp quyền theo database, table và mức chi tiết được hỗ trợ; phối hợp IAM, S3 và data access để kiểm soát truy vấn.','Nhiều nhóm chia sẻ data lake nhưng chỉ được đọc các bảng hoặc cột cho phép.','Không thay thế S3 làm nơi lưu dữ liệu. Cần hiểu cả IAM lẫn quyền Lake Formation, tránh bỏ qua quyền truy cập S3 trực tiếp.','s3,glue,athena','lake-formation'],
['cloudwatch','Amazon CloudWatch','governance','Metrics, logs và cảnh báo vận hành','Dịch vụ quan sát trạng thái ứng dụng và tài nguyên bằng metrics, logs, dashboard và alarm. Trả lời hệ thống đang hoạt động ra sao.','Alarm đánh giá metric theo cửa sổ thời gian và có thể gửi SNS hay kích hoạt scaling. Agent thu thập thêm OS metrics/logs; metric filter có thể tạo metric từ log.','Cảnh báo latency hoặc lỗi tăng, theo dõi CPU và Auto Scaling theo tải.','EC2 không tự gửi mọi chỉ số như RAM ở mức OS theo mặc định. CloudTrail trả lời ai gọi API; Config theo dõi cấu hình, hai việc khác nhau.','sns,asg,ec2,lambda,cloudtrail','cloudwatch'],
['cloudtrail','AWS CloudTrail','governance','Dấu vết hành động API','Dịch vụ ghi nhận hoạt động tài khoản và các sự kiện API được hỗ trợ để audit và điều tra. Cho biết ai đã làm gì, khi nào, từ đâu.','Event history có phạm vi và thời gian lưu riêng; trail chuyển log tới S3. Data events như truy cập object cần cấu hình phù hợp và có thể phát sinh chi phí riêng.','Điều tra người thay security group, thao tác IAM hay hoạt động quản trị database.','Không phải log ứng dụng hoặc công cụ tự đánh giá tuân thủ cấu hình. Không mặc định mọi data event đều đã được ghi.','s3,iam,config,eventbridge','cloudtrail'],
['config','AWS Config','governance','Lịch sử cấu hình và compliance','Dịch vụ ghi nhận cấu hình tài nguyên được hỗ trợ và đánh giá với rule tuân thủ. Cho biết tài nguyên đã có cấu hình gì và đáp ứng chính sách hay chưa.','Configuration recorder theo dõi tài nguyên; rule đánh giá theo thay đổi hoặc lịch. Conformance pack gom rule; remediation có thể tích hợp automation.','Phát hiện bucket hoặc security group sai quy định, theo dõi thay đổi cấu hình qua thời gian.','Config tìm cấu hình lệch, CloudTrail ghi hành động API. Bật rule không tự sửa tài nguyên nếu chưa cấu hình remediation.','cloudtrail,ssm,securityhub','config'],
['cloudformation','AWS CloudFormation','governance','Hạ tầng dưới dạng mã','Dịch vụ mô tả tài nguyên bằng template và triển khai thành stack. Giúp lặp lại môi trường, kiểm soát thay đổi và giảm cấu hình thủ công.','Template khai báo resource và dependency. Change set xem thay đổi dự kiến; stack update thực hiện; drift detection phát hiện một số thay đổi bên ngoài được hỗ trợ.','Dựng cùng kiến trúc VPC/ALB/EC2 cho dev và production, hoặc khôi phục hạ tầng ở Region khác.','Update có thể thay thế resource và ảnh hưởng dữ liệu. Dùng deletion/retention policy phù hợp; template không tự backup database.','vpc,ec2,rds,organizations','cloudformation'],
['organizations','AWS Organizations','governance','Quản lý và giới hạn nhiều tài khoản','Dịch vụ gom AWS account thành organization, nhóm trong OU, áp chính sách và hỗ trợ consolidated billing. Tài khoản là ranh giới hữu ích để cô lập workload.','SCP đặt giới hạn quyền tối đa cho principal trong member account thuộc phạm vi. Kết hợp account theo môi trường và thiết lập quyền liên tài khoản qua IAM role.','Tách production, dev và tài khoản log; chặn sử dụng Region hoặc thao tác nhạy cảm theo chính sách.','SCP không cấp quyền, không áp dụng giống permission policy và có ngoại lệ phạm vi như management account. Vẫn cần IAM grant thực tế.','iam,controltower,backup,costexplorer','organizations'],
['controltower','AWS Control Tower','governance','Landing zone nhiều tài khoản','Dịch vụ thiết lập và quản trị môi trường AWS nhiều account theo hướng có nền tảng quản trị sẵn. Dùng Organizations và các dịch vụ liên quan để chuẩn hóa khởi tạo account.','Landing zone, account factory và control hỗ trợ quản lý governance nhất quán. Các control có cơ chế thực thi/phát hiện khác nhau.','Doanh nghiệp bắt đầu môi trường multi-account cần quy trình tạo account và rào chắn thống nhất.','Không thay thế Organizations hay mọi quy trình vận hành. Kiểm tra Region và control được bật; landing zone vẫn cần thiết kế mạng và truy cập.','organizations,iam,config,cloudtrail','controltower'],
['ssm','AWS Systems Manager','governance','Quản trị fleet và tự động hóa','Tập hợp khả năng quản lý máy và ứng dụng như Session Manager, Run Command, Patch Manager, Automation và Parameter Store.','Managed node cần agent, role và kết nối dịch vụ phù hợp. Session Manager hỗ trợ truy cập vận hành mà không phải mở SSH inbound; Automation chạy quy trình quản trị.','Vá fleet EC2, chạy lệnh hàng loạt, truy cập máy private và lưu cấu hình ứng dụng.','Không mở SSH không có nghĩa không cần IAM và logging. Private subnet cần endpoint phù hợp hoặc đường ra dịch vụ.','ec2,iam,privatelink,secretsmanager','systems-manager'],
['dms','AWS Database Migration Service','migration','Di chuyển và sao chép dữ liệu database','Dịch vụ di chuyển dữ liệu giữa database nguồn và đích được hỗ trợ. Có thể thực hiện full load rồi tiếp tục capture thay đổi (CDC) để giảm downtime khi chuyển đổi.','Thiết lập endpoint nguồn/đích, replication và task. Với chuyển engine, schema và code SQL có thể cần công cụ conversion và chỉnh sửa riêng.','Di chuyển database tại chỗ lên RDS/Aurora hoặc đồng bộ dữ liệu cho giai đoạn cutover.','DMS không tự biến mọi stored procedure hay schema sang engine mới. Kiểm tra compatibility, validation và thời điểm cutover.','rds,aurora,documentdb,vpn','dms'],
['datasync','AWS DataSync','migration','Truyền dữ liệu file/object trực tuyến','Dịch vụ tự động truyền dữ liệu giữa các hệ thống lưu trữ được hỗ trợ, gồm một số nguồn tại chỗ và dịch vụ AWS. Tập trung vào migration hoặc đồng bộ định kỳ.','Task xác định source, destination và option kiểm tra/truyền dữ liệu. Agent dùng cho các loại vị trí cần agent; dữ liệu truyền trên đường mạng có sẵn.','Chuyển NAS vào EFS/FSx hoặc đưa file từ datacenter lên S3.','DataSync dùng đường mạng; không phải thiết bị offline như Snow Family. Khác Storage Gateway cung cấp giao diện truy cập hybrid liên tục cho ứng dụng.','s3,efs,fsx,storagegateway','datasync'],
['mgn','Application Migration Service','migration','Lift-and-shift máy chủ sang AWS','Dịch vụ hỗ trợ di chuyển server sang AWS bằng sao chép block và khởi chạy máy chuyển đổi trên EC2. Mục tiêu giảm thay đổi ứng dụng khi rehost.','Cài thành phần replication theo nguồn hỗ trợ, đồng bộ dữ liệu, chạy test instance rồi cutover theo kế hoạch.','Di chuyển server truyền thống khi chưa sẵn sàng refactor sang container hoặc serverless.','Di chuyển nguyên máy không tự tối ưu ứng dụng, license hay chi phí. Kiểm thử mạng, boot, dependency và kế hoạch rollback trước cutover.','ec2,ebs,vpc','application-migration-service'],
['transfer','AWS Transfer Family','migration','SFTP/FTPS/FTP và truyền file được quản lý','Dịch vụ cung cấp giao thức truyền file và các khả năng trao đổi dữ liệu được hỗ trợ, tích hợp lưu trữ AWS như S3 và EFS.','Cấu hình endpoint, identity provider và mapping quyền/đường dẫn tới storage. Hỗ trợ workflow xử lý file theo khả năng tương ứng.','Đối tác dùng SFTP gửi file vào S3 mà không tự vận hành SFTP server trên EC2.','Protocol support và kiểu endpoint phụ thuộc cấu hình. FTP không mã hóa; chọn giao thức và đường truyền theo yêu cầu bảo mật.','s3,efs,iam','aws-transfer-family'],
['costexplorer','AWS Cost Explorer','cost','Phân tích chi phí và mức sử dụng','Công cụ xem chi phí lịch sử, phân nhóm theo dịch vụ/tài khoản/tag và phân tích xu hướng. Hữu ích để tìm nguồn tăng chi phí và xem dự báo được hỗ trợ.','Lọc và group dữ liệu chi phí theo khoảng thời gian. Cost allocation tags cần được kích hoạt phù hợp để phân bổ chi phí theo nhóm nghiệp vụ.','Tìm dịch vụ tăng tiền tháng này hoặc so sánh chi phí theo môi trường.','Dữ liệu chi phí không phải tức thời. Cost Explorer phân tích; Budgets gửi cảnh báo theo ngưỡng; báo cáo CUR cho dữ liệu chi tiết.','budgets,organizations,savingsplans','aws-cost-management/aws-cost-explorer'],
['budgets','AWS Budgets','cost','Theo dõi ngân sách và gửi cảnh báo','Công cụ đặt budget cho chi phí, usage hoặc chỉ số được hỗ trợ và cảnh báo khi giá trị thực tế/dự báo đạt điều kiện.','Thiết lập scope, kỳ ngân sách, threshold và người nhận. Budget Actions có thể thực hiện tác vụ được cấu hình khi đáp ứng điều kiện.','Cảnh báo sớm tài khoản dev vượt ngân sách hoặc mức dùng tăng bất thường.','Budget không phải hard cap bảo đảm dừng mọi chi phí đúng thời điểm. Cập nhật có độ trễ; phải cấu hình action riêng nếu cần.','costexplorer,sns,organizations','aws-cost-management/aws-budgets'],
['savingsplans','Savings Plans & EC2 purchasing','cost','Chọn mô hình giá theo workload','On-Demand trả theo mức dùng; Spot tận dụng capacity dư có thể gián đoạn; Savings Plans giảm giá đổi lấy cam kết mức chi tiêu compute theo giờ trong thời hạn.','Compute Savings Plans linh hoạt hơn giữa các lựa chọn compute được hỗ trợ; EC2 Instance Savings Plans có ràng buộc theo family/Region. Reserved Instances có các thuộc tính và phạm vi riêng.','Workload nền ổn định → cân nhắc cam kết; batch chịu gián đoạn → Spot; nhu cầu khó đoán → On-Demand.','Cam kết trả tiền không bảo đảm tiết kiệm nếu không sử dụng hết. Savings Plans không đặt trước capacity; cần capacity reservation khi có yêu cầu giữ chỗ.','ec2,fargate,lambda,costexplorer','savingsplans']
];
