 {id:'async',title:'Đơn hàng bất đồng bộ',tag:'Decoupling',desc:'Một sự kiện được chia cho nhiều nhóm xử lý. Queue hấp thụ đột biến và giúp mỗi nhóm retry độc lập.',nodes:['apigateway','lambda','sns','sqs','ecs','dynamodb'],edges:[[0,1,'Tiếp nhận đơn'],[1,2,'Publish event'],[2,3,'Fan-out tới queue'],[3,4,'Worker poll / ack'],[4,5,'Cập nhật trạng thái']],steps:['API ghi nhận đơn và xác nhận tiếp nhận theo thiết kế ứng dụng. Nếu vừa lưu DB vừa publish, cân nhắc transactional outbox để tránh mất sự kiện.','SNS phát event tới queue của từng nhóm như kho, thông báo và phân tích; hình minh họa một nhánh.','ECS worker đọc SQS, xử lý rồi xóa message. Khi lỗi, message hiện lại sau visibility timeout.','Cấu hình DLQ, alarm theo tuổi/backlog, và idempotency key theo order ID để tránh xử lý trùng.'],tradeoff:'Hệ thống trở thành eventually consistent. Thiết kế trạng thái đang xử lý, timeout, xử lý lỗi và bù trừ cho nghiệp vụ.',extras:['stepfunctions','eventbridge','asg','cloudwatch']},
 {id:'lake',title:'Streaming vào data lake',tag:'Data & analytics',desc:'Thu thập sự kiện liên tục, lưu ở S3 và phân tích bằng SQL. Tách lưu trữ lâu dài khỏi compute phân tích.',nodes:['kinesis','firehose','s3','glue','athena','lakeformation'],edges:[[0,1,'Đọc stream'],[1,2,'Buffer & delivery'],[2,3,'Crawler đọc schema'],[3,4,'Metadata bảng'],[2,4,'Athena đọc dữ liệu'],[5,4,'Kiểm soát quyền']],steps:['Ứng dụng gửi record vào Kinesis Data Streams với partition key phân bổ hợp lý.','Firehose đọc dữ liệu, buffer và ghi vào S3. Dùng partition và định dạng cột phù hợp truy vấn.','Glue crawler/catalog mô tả schema; dữ liệu vẫn nằm trong S3.','Athena sử dụng catalog và quét object S3 để trả kết quả SQL; Lake Formation quản trị quyền dữ liệu theo tích hợp.'],tradeoff:'Đây là luồng phân tích, không thay database giao dịch. Buffering và catalog update làm tăng độ trễ; cân nhắc consumer trực tiếp nếu cần phản ứng tức thì.',extras:['kms','redshift','lambda']},
 {id:'hybrid',title:'Kết nối hybrid doanh nghiệp',tag:'Networking',desc:'Kết nối datacenter với nhiều VPC qua hub, đồng thời giữ đường truyền dự phòng và truy cập dịch vụ private.',nodes:['directconnect','vpn','transitgateway','vpc','privatelink','s3'],edges:[[0,2,'Qua DX gateway'],[1,2,'IPsec dự phòng'],[2,3,'VPC attachment'],[3,4,'Private endpoint'],[4,5,'Truy cập S3']],steps:['Mạng datacenter nối Direct Connect; đường tới Transit Gateway đi qua Direct Connect gateway và transit virtual interface phù hợp.','Site-to-Site VPN có thể bổ sung đường dự phòng; thiết kế BGP và route preference để chuyển tuyến đúng.','Transit Gateway là hub kết nối VPC; cần route ở hub và từng subnet liên quan.','S3 gateway endpoint phù hợp traffic xuất phát từ VPC. Truy cập S3 private từ on-premises qua hybrid cần S3 interface endpoint và cấu hình DNS phù hợp.'],tradeoff:'Direct Connect không mặc định mã hóa. Thiết kế dự phòng thiết bị, đường truyền, địa điểm và encryption theo yêu cầu; hình rút gọn không phải cấu hình mạng triển khai sẵn.',extras:['route53','nat','iam']},
 {id:'security',title:'Phát hiện và phản ứng bảo mật',tag:'Security',desc:'Thu thập dấu vết, tìm mối đe dọa, tập hợp finding rồi tự động hóa phản ứng có kiểm soát.',nodes:['cloudtrail','guardduty','securityhub','eventbridge','lambda','sns'],edges:[[0,1,'Nguồn telemetry'],[1,2,'Security finding'],[2,3,'Sự kiện finding'],[3,4,'Remediation'],[3,5,'Thông báo']],steps:['CloudTrail ghi các hành động API theo cấu hình; GuardDuty phân tích nguồn dữ liệu được hỗ trợ để tìm hành vi đáng ngờ.','Security Hub tập hợp finding; Inspector và Macie bổ sung lỗ hổng và dữ liệu nhạy cảm.','EventBridge lọc finding theo mức độ và ngữ cảnh, gửi SNS hoặc gọi quy trình xử lý.','Lambda có quyền giới hạn để thực hiện biện pháp đã được kiểm duyệt; giữ log và cân nhắc bước phê duyệt cho thao tác tác động lớn.'],tradeoff:'Finding là dấu hiệu cần đánh giá, không luôn là xâm nhập đã xác nhận. Tự động cô lập sai có thể làm gián đoạn ứng dụng.',extras:['inspector','macie','iam','config','stepfunctions']}
