export const glossary = [
 ['Region / Availability Zone','Region là khu vực địa lý chứa nhiều AZ. AZ là một hoặc nhiều datacenter có hạ tầng độc lập tương đối. Multi-AZ tăng khả năng chịu lỗi trong một Region; multi-Region hỗ trợ yêu cầu địa lý và thảm họa cấp Region.'],
 ['High availability / Fault tolerance','High availability giảm thời gian gián đoạn bằng dự phòng và failover. Fault tolerance hướng đến tiếp tục phục vụ khi thành phần hỏng. Chỉ đặt hai EC2 chưa đủ nếu database hoặc dependency vẫn là điểm lỗi đơn.'],
 ['RPO / RTO','RPO: mức mất dữ liệu tối đa chấp nhận được, đo theo thời gian. RTO: khoảng thời gian tối đa chấp nhận để khôi phục dịch vụ. Replication, backup và thử nghiệm recovery quyết định có đạt hai mục tiêu hay không.'],
 ['Scale up / Scale out','Scale up tăng tài nguyên một máy; scale out tăng số máy. Scale out thường cần ứng dụng stateless hoặc trạng thái được đưa vào kho dùng chung, cùng cơ chế phân phối tải.'],
 ['Stateless / Stateful','Stateless không giữ trạng thái phiên bắt buộc trên một instance cụ thể. Stateful giữ dữ liệu hoặc phiên phải bảo toàn. Đưa session ra ElastiCache/DynamoDB và file ra S3/EFS giúp thay máy an toàn hơn.'],
 ['Synchronous / Asynchronous','Đồng bộ: caller chờ kết quả xử lý. Bất đồng bộ: caller gửi công việc rồi theo dõi kết quả sau. Queue giảm liên kết và đệm tải nhưng cần thiết kế retry, idempotency và trạng thái xử lý.'],
 ['Idempotency','Xử lý cùng một yêu cầu nhiều lần vẫn tạo hiệu quả nghiệp vụ như một lần. Ví dụ lưu idempotency key của đơn hàng, kiểm tra điều kiện cập nhật trước khi ghi hoặc thanh toán để tránh side effect trùng.'],
 ['Encryption at rest / in transit','At rest bảo vệ dữ liệu lưu trữ như S3/EBS; in transit bảo vệ dữ liệu khi truyền bằng TLS/IPsec. Mã hóa không thay cho phân quyền: ứng dụng có quyền giải mã vẫn có thể đọc dữ liệu.'],
 ['Least privilege / Shared responsibility','Least privilege chỉ cấp đúng action và resource cần thiết. AWS bảo vệ hạ tầng cloud; trách nhiệm của bạn thay đổi theo dịch vụ, nhưng vẫn gồm dữ liệu, danh tính và cấu hình. Trên EC2 bạn còn chịu trách nhiệm OS.'],
 ['Durability / Availability / Backup','Durability nói về khả năng giữ dữ liệu; availability nói về khả năng truy cập. Backup cho phép khôi phục trạng thái đã lưu. Replication có thể sao chép cả thao tác xóa nhầm nên không tự thay thế backup.']
];
